export interface BookMetadata {
  title: string;
  author: string;
  genre: string;
  summary: string;
  hashtags: string[];
  vibe: string; // e.g., "Dark Academica", "Tech Optimism"
}

export interface Book {
  id: string;
  pdfUrl: string;
  previewImage: string;
  metadata: BookMetadata;
  uploadDate: number;
  likes: number;
  shares: number;
}

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

export const processPdf = async (file: File): Promise<{ previewImage: string; textContent: string }> => {
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

  // 1. Get Preview Image of the first page
  const page = await pdf.getPage(1);
  const viewport = page.getViewport({ scale: 1.5 });
  const canvas = document.createElement('canvas');
  const context = canvas.getContext('2d');

  if (!context) throw new Error('Canvas context not available');

  canvas.height = viewport.height;
  canvas.width = viewport.width;

  await page.render({ canvasContext: context, viewport }).promise;
  const previewImage = canvas.toDataURL('image/jpeg', 0.8);

  // 2. Get Text Content from first 3 pages (for AI analysis)
  let textContent = '';
  const numPagesToExtract = Math.min(pdf.numPages, 3);
  for (let i = 1; i <= numPagesToExtract; i++) {
    const pageText = await pdf.getPage(i);
    const content = await pageText.getTextContent();
    textContent += content.items.map((item: any) => item.str).join(' ') + '\n';
  }

  return { previewImage, textContent };
};

import { GoogleGenAI, Type } from "@google/genai";
import { BookMetadata } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getBookMetadata = async (pdfText: string): Promise<BookMetadata> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Analyze the following book text and provide metadata in JSON format.
    Provide a catchy social-media style summary.

    Text snippet: ${pdfText.substring(0, 5000)}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          author: { type: Type.STRING },
          genre: { type: Type.STRING },
          summary: { type: Type.STRING },
          hashtags: { 
            type: Type.ARRAY, 
            items: { type: Type.STRING } 
          },
          vibe: { type: Type.STRING }
        },
        required: ["title", "author", "genre", "summary", "hashtags", "vibe"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");
  return JSON.parse(text);
};

