import React, { useState, useEffect, useRef } from 'react';
import { X, Upload, FileText, Loader2, Sparkles, CheckCircle } from 'lucide-react';
import { processPdf } from '../services/pdfService';
import { getBookMetadata } from '../services/geminiService';
import { Book } from '../types';

interface UploadModalProps {
  onUploadComplete: (book: Book) => void;
}

const UploadModal: React.FC<UploadModalProps> = ({ onUploadComplete }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [status, setStatus] = useState<'idle' | 'processing' | 'analyzing' | 'success' | 'error'>('idle');
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleOpen = () => setIsOpen(true);
    window.addEventListener('open-upload-modal', handleOpen);
    return () => window.removeEventListener('open-upload-modal', handleOpen);
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || file.type !== 'application/pdf') {
      setError('Please upload a valid PDF file.');
      return;
    }

    try {
      setStatus('processing');
      setError(null);

      // 1. Convert PDF to image and text
      const { previewImage, textContent } = await processPdf(file);

      // 2. Use Gemini to analyze text
      setStatus('analyzing');
      const metadata = await getBookMetadata(textContent);

      const newBook: Book = {
        id: Math.random().toString(36).substr(2, 9),
        pdfUrl: URL.createObjectURL(file), // In real app, this would be a cloud URL
        previewImage,
        metadata,
        uploadDate: Date.now(),
        likes: Math.floor(Math.random() * 100),
        shares: Math.floor(Math.random() * 50)
      };

      setStatus('success');
      setTimeout(() => {
        onUploadComplete(newBook);
        setIsOpen(false);
        setStatus('idle');
      }, 1500);

    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Something went wrong during processing.');
      setStatus('error');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm"
        onClick={() => status !== 'processing' && status !== 'analyzing' && setIsOpen(false)}
      />

      <div className="relative bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
        <div className="p-6">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-bold">Publish New Book</h2>
            <button 
              onClick={() => setIsOpen(false)}
              className="p-2 hover:bg-slate-100 rounded-full transition-colors"
            >
              <X size={20} />
            </button>
          </div>

          <div className="space-y-6">
            {status === 'idle' || status === 'error' ? (
              <div 
                onClick={() => fileInputRef.current?.click()}
                className={`border-2 border-dashed rounded-2xl p-10 text-center cursor-pointer transition-all
                  ${status === 'error' ? 'border-red-300 bg-red-50' : 'border-slate-200 hover:border-indigo-400 hover:bg-indigo-50/50'}
                `}
              >
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  accept="application/pdf"
                  onChange={handleFileChange}
                />
                <div className="bg-indigo-100 text-indigo-600 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Upload size={32} />
                </div>
                <h3 className="text-lg font-semibold mb-2">Drop your PDF here</h3>
                <p className="text-slate-500 text-sm">We'll automatically generate a social page for it using AI</p>
                {error && <p className="text-red-500 mt-4 text-sm font-medium">{error}</p>}
              </div>
            ) : (
              <div className="py-12 flex flex-col items-center justify-center text-center">
                <div className="relative mb-6">
                  {status === 'processing' || status === 'analyzing' ? (
                    <div className="w-20 h-20 rounded-full border-4 border-indigo-100 border-t-indigo-600 animate-spin" />
                  ) : (
                    <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center animate-bounce">
                      <CheckCircle size={40} />
                    </div>
                  )}
                  <div className="absolute inset-0 flex items-center justify-center">
                    {status === 'processing' && <FileText className="text-indigo-600 animate-pulse" size={32} />}
                    {status === 'analyzing' && <Sparkles className="text-indigo-600 animate-pulse" size={32} />}
                  </div>
                </div>

                <h3 className="text-xl font-bold mb-2">
                  {status === 'processing' && 'Extracting Pages...'}
                  {status === 'analyzing' && 'AI Analysis in Progress...'}
                  {status === 'success' && 'Published Successfully!'}
                </h3>
                <p className="text-slate-500">
                  {status === 'processing' && 'Rendering previews and indexing text content.'}
                  {status === 'analyzing' && 'Gemini is reading your book to create social metadata.'}
                  {status === 'success' && 'Redirecting you to the storefront.'}
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

