import React, { useEffect, useRef, useState, useCallback } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { Book } from '../types';
import { 
  ChevronLeft, 
  ChevronRight, 
  ZoomIn, 
  ZoomOut, 
  Maximize, 
  X, 
  Loader2,
  Maximize2,
  Minimize2
} from 'lucide-react';

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];

interface BookViewerProps {
  books: Book[];
}

const BookViewer: React.FC<BookViewerProps> = ({ books }) => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const book = books.find(b => b.id === id);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [pdf, setPdf] = useState<any>(null);
  const [pageNum, setPageNum] = useState(1);
  const [numPages, setNumPages] = useState(0);
  const [scale, setScale] = useState(1.2);
  const [loading, setLoading] = useState(true);
  const [isFullscreen, setIsFullscreen] = useState(false);

  // Load PDF document
  useEffect(() => {
    if (!book) return;

    const loadPdf = async () => {
      try {
        setLoading(true);
        const loadingTask = pdfjsLib.getDocument(book.pdfUrl);
        const pdfDoc = await loadingTask.promise;
        setPdf(pdfDoc);
        setNumPages(pdfDoc.numPages);
        setLoading(false);
      } catch (error) {
        console.error("Error loading PDF:", error);
        setLoading(false);
      }
    };

    loadPdf();
  }, [book]);

  // Render current page
  const renderPage = useCallback(async (num: number, currentScale: number) => {
    if (!pdf || !canvasRef.current) return;

    const page = await pdf.getPage(num);
    const viewport = page.getViewport({ scale: currentScale });
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    if (!context) return;

    canvas.height = viewport.height;
    canvas.width = viewport.width;

    const renderContext = {
      canvasContext: context,
      viewport: viewport,
    };

    await page.render(renderContext).promise;
  }, [pdf]);

  useEffect(() => {
    if (pdf) {
      renderPage(pageNum, scale);
    }
  }, [pdf, pageNum, scale, renderPage]);

  // Handle Resize
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current && pdf) {
        // Auto-fit to width if smaller screen
        const containerWidth = containerRef.current.clientWidth - 40;
        // Simple logic to find a reasonable scale
        // We'll leave it to the user for now but could auto-adjust here
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [pdf]);

  if (!book) return null;

  const changePage = (offset: number) => {
    const newPage = pageNum + offset;
    if (newPage >= 1 && newPage <= numPages) {
      setPageNum(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  return (
    <div ref={containerRef} className="fixed inset-0 z-[100] bg-slate-950 flex flex-col text-white overflow-hidden">
      {/* Header Toolbar */}
      <div className="h-16 flex items-center justify-between px-4 md:px-8 bg-slate-900/50 border-b border-white/5 backdrop-blur-md">
        <div className="flex items-center gap-4">
          <Link to={`/book/${id}`} className="p-2 hover:bg-white/10 rounded-full transition-colors text-slate-400 hover:text-white">
            <X size={24} />
          </Link>
          <div className="hidden md:block">
            <h1 className="font-bold text-sm truncate max-w-[200px]">{book.metadata.title}</h1>
            <p className="text-[10px] text-slate-400 uppercase tracking-widest">{book.metadata.author}</p>
          </div>
        </div>

        <div className="flex items-center gap-2 md:gap-6">
          <div className="flex items-center bg-white/5 rounded-xl p-1">
            <button 
              onClick={() => setScale(s => Math.max(0.5, s - 0.2))}
              className="p-2 hover:bg-white/10 rounded-lg transition-colors"
            >
              <ZoomOut size={18} />
            </button>
            <span className="w-16 text-center text-xs font-mono">{Math.round(scale * 100)}%</span>
            <button 
              onClick={() => setScale(s => Math.min(3, s + 0.2))}
              className="p-2 hover:bg-white/10 rounded-lg transition-colors"
            >
              <ZoomIn size={18} />
            </button>
          </div>

          <button 
            onClick={toggleFullscreen}
            className="p-2 hover:bg-white/10 rounded-full text-slate-400 hover:text-white"
          >
            {isFullscreen ? <Minimize2 size={20} /> : <Maximize2 size={20} />}
          </button>
        </div>
      </div>

      {/* Main View Area */}
      <div className="flex-1 overflow-auto bg-slate-950 flex flex-col items-center py-8 px-4 scroll-smooth">
        {loading ? (
          <div className="flex flex-col items-center justify-center h-full gap-4">
            <Loader2 size={48} className="text-indigo-500 animate-spin" />
            <p className="text-slate-400 font-medium">Preparing your book...</p>
          </div>
        ) : (
          <div className="relative group">
            <canvas 
              ref={canvasRef} 
              className="shadow-2xl rounded-sm max-w-full h-auto bg-white"
            />

            {/* Overlay indicators */}
            <div className="absolute inset-y-0 left-0 w-1/4 opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
              <button 
                onClick={() => changePage(-1)}
                disabled={pageNum <= 1}
                className="ml-4 p-4 bg-black/50 hover:bg-black/80 rounded-full disabled:opacity-0 disabled:cursor-default transition-all"
              >
                <ChevronLeft size={32} />
              </button>
            </div>
            <div className="absolute inset-y-0 right-0 w-1/4 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-end">
              <button 
                onClick={() => changePage(1)}
                disabled={pageNum >= numPages}
                className="mr-4 p-4 bg-black/50 hover:bg-black/80 rounded-full disabled:opacity-0 disabled:cursor-default transition-all"
              >
                <ChevronRight size={32} />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Bottom Controls */}
      {!loading && (
        <div className="h-16 flex items-center justify-center px-4 bg-slate-900/80 border-t border-white/5 backdrop-blur-md">
          <div className="flex items-center gap-4 bg-white/5 px-4 py-2 rounded-2xl">
             <button 
                onClick={() => changePage(-1)}
                disabled={pageNum <= 1}
                className="p-1.5 hover:bg-white/10 rounded-lg disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeft size={20} />
              </button>

              <div className="flex items-center gap-2 text-sm font-bold">
                <span className="bg-indigo-600 px-2 py-0.5 rounded text-xs">PAGE</span>
                <span>{pageNum}</span>
                <span className="text-slate-500">/</span>
                <span className="text-slate-500">{numPages}</span>
              </div>

              <button 
                onClick={() => changePage(1)}
                disabled={pageNum >= numPages}
                className="p-1.5 hover:bg-white/10 rounded-lg disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronRight size={20} />
              </button>
          </div>
        </div>
      )}
    </div>
  );
};

