import React, { useState, useEffect, useRef } from 'react';
import { X, Upload, FileText, CheckCircle, Sparkles, Hash, Type as TypeIcon, User, Tag } from 'lucide-react';
import { processPdf } from '../services/pdfService';
import { Book, BookMetadata } from '../types';

interface UploadModalProps {
  onUploadComplete: (book: Book) => void;
}

const UploadModal: React.FC<UploadModalProps> = ({ onUploadComplete }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [status, setStatus] = useState<'idle' | 'processing' | 'building' | 'success' | 'error'>('idle');
  const [error, setError] = useState<string | null>(null);
  const [previewImg, setPreviewImg] = useState<string>('');
  const [pdfFile, setPdfFile] = useState<File | null>(null);

  // Manual Form State
  const [formData, setFormData] = useState<BookMetadata>({
    title: '',
    author: '',
    genre: 'General',
    hashtags: [],
    vibe: 'Modern'
  });
  const [tagInput, setTagInput] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleOpen = () => {
      setIsOpen(true);
      setStatus('idle');
      setFormData({ title: '', author: '', genre: 'General', hashtags: [], vibe: 'Modern' });
    };
    window.addEventListener('open-upload-modal', handleOpen);
    return () => window.removeEventListener('open-upload-modal', handleOpen);
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || file.type !== 'application/pdf') {
      setError('Please upload a valid PDF file.');
      return;
    }

    try {
      setStatus('processing');
      setError(null);
      setPdfFile(file);

      const { previewImage } = await processPdf(file);
      setPreviewImg(previewImage);

      // Instead of AI, we move to the building phase (manual form)
      setStatus('building');
    } catch (err: any) {
      setError(err.message || 'Error processing PDF.');
      setStatus('error');
    }
  };

  const handlePublish = () => {
    if (!formData.title || !formData.author || !pdfFile) {
      setError('Title and Author are required.');
      return;
    }

    const newBook: Book = {
      id: Math.random().toString(36).substr(2, 9),
      pdfUrl: URL.createObjectURL(pdfFile),
      previewImage: previewImg,
      metadata: formData,
      uploadDate: Date.now(),
      likes: 0,
      shares: 0
    };

    setStatus('success');
    setTimeout(() => {
      onUploadComplete(newBook);
      setIsOpen(false);
    }, 1000);
  };

  const addTag = () => {
    if (tagInput && !formData.hashtags.includes(tagInput)) {
      setFormData({ ...formData, hashtags: [...formData.hashtags, tagInput.startsWith('#') ? tagInput : `#${tagInput}`] });
      setTagInput('');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-slate-900/80 backdrop-blur-md"
        onClick={() => status !== 'processing' && setIsOpen(false)}
      />

      <div className="relative bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
        <div className="p-8">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black text-slate-900 tracking-tight">
              {status === 'building' ? 'Build Social Page' : 'Publish PDF'}
            </h2>
            <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
              <X size={24} />
            </button>
          </div>

          {status === 'idle' || status === 'error' ? (
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="border-4 border-dashed border-slate-100 rounded-[2rem] p-16 text-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/30 transition-all group"
            >
              <input type="file" ref={fileInputRef} className="hidden" accept="application/pdf" onChange={handleFileChange} />
              <div className="bg-indigo-100 text-indigo-600 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-6 group-hover:scale-110 group-hover:rotate-6 transition-transform">
                <Upload size={40} />
              </div>
              <h3 className="text-xl font-bold mb-2">Select Book PDF</h3>
              <p className="text-slate-400">The first page will be used as the cover automatically.</p>
              {error && <p className="text-red-500 mt-4 font-bold">{error}</p>}
            </div>
          ) : status === 'processing' ? (
            <div className="py-20 text-center">
              <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-6" />
              <p className="text-lg font-bold text-slate-600">Extracting Cover Image...</p>
            </div>
          ) : status === 'building' ? (
            <div className="grid md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <div className="aspect-[3/4] rounded-2xl overflow-hidden border border-slate-200 shadow-inner bg-slate-50">
                  <img src={previewImg} className="w-full h-full object-cover" alt="Preview" />
                </div>
                <p className="text-center text-xs font-bold text-slate-400 uppercase tracking-widest">Automatic Cover Generated</p>
              </div>

              <div className="space-y-4">
                <div className="relative">
                  <TypeIcon size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder="Book Title" 
                    className="w-full bg-slate-50 border-none rounded-2xl py-4 pl-12 pr-4 font-bold focus:ring-2 focus:ring-indigo-500 transition-all"
                    value={formData.title}
                    onChange={e => setFormData({...formData, title: e.target.value})}
                  />
                </div>
                <div className="relative">
                  <User size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder="Author Name" 
                    className="w-full bg-slate-50 border-none rounded-2xl py-4 pl-12 pr-4 font-bold focus:ring-2 focus:ring-indigo-500 transition-all"
                    value={formData.author}
                    onChange={e => setFormData({...formData, author: e.target.value})}
                  />
                </div>
                <div className="grid grid-cols-2 gap-3">
                   <div className="relative">
                    <Tag size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Genre" 
                      className="w-full bg-slate-50 border-none rounded-xl py-3 pl-10 pr-4 text-sm font-bold focus:ring-2 focus:ring-indigo-500"
                      value={formData.genre}
                      onChange={e => setFormData({...formData, genre: e.target.value})}
                    />
                  </div>
                  <div className="relative">
                    <Sparkles size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Vibe" 
                      className="w-full bg-slate-50 border-none rounded-xl py-3 pl-10 pr-4 text-sm font-bold focus:ring-2 focus:ring-indigo-500"
                      value={formData.vibe}
                      onChange={e => setFormData({...formData, vibe: e.target.value})}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <div className="flex gap-2">
                    <input 
                      type="text" 
                      placeholder="Add hashtags..." 
                      className="flex-1 bg-slate-50 border-none rounded-xl py-3 px-4 text-sm font-bold"
                      value={tagInput}
                      onChange={e => setTagInput(e.target.value)}
                      onKeyPress={e => e.key === 'Enter' && addTag()}
                    />
                    <button onClick={addTag} className="bg-slate-900 text-white px-4 rounded-xl font-bold text-sm">Add</button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {formData.hashtags.map(t => (
                      <span key={t} className="bg-indigo-50 text-indigo-600 px-2 py-1 rounded-lg text-xs font-black flex items-center gap-1">
                        {t}
                        <X size={12} className="cursor-pointer" onClick={() => setFormData({...formData, hashtags: formData.hashtags.filter(x => x !== t)})} />
                      </span>
                    ))}
                  </div>
                </div>
                <button 
                  onClick={handlePublish}
                  className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-indigo-100 hover:bg-indigo-700 hover:-translate-y-1 transition-all"
                >
                  Publish Social Page
                </button>
              </div>
            </div>
          ) : (
            <div className="py-12 text-center">
               <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce">
                <CheckCircle size={40} />
              </div>
              <h3 className="text-2xl font-black mb-2">Success!</h3>
              <p className="text-slate-500 font-bold">Your book is now live on the shelf.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default UploadModal;

