import { Book } from '../types';

const DB_NAME = 'SocialBookDB';
const STORE_NAME = 'books';
const DB_VERSION = 1;

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const saveBook = async (book: Book, pdfBlob: Blob): Promise<void> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    // Store the blob directly in the object
    const data = { ...book, pdfBlob };
    const request = store.put(data);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
};

export const getAllBooks = async (): Promise<Book[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => {
      // Reconstruct blob URLs for the current session
      const books = request.result.map(item => ({
        ...item,
        pdfUrl: URL.createObjectURL(item.pdfBlob)
      }));
      resolve(books);
    };
    request.onerror = () => reject(request.error);
  });
};

export const getBookById = async (id: string): Promise<Book | null> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.get(id);
    request.onsuccess = () => {
      if (!request.result) return resolve(null);
      const book = {
        ...request.result,
        pdfUrl: URL.createObjectURL(request.result.pdfBlob)
      };
      resolve(book);
    };
    request.onerror = () => reject(request.error);
  });
};

