import { PageContent } from '../types';

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

export const deconstructPdf = async (file: File): Promise<{ previewImage: string; content: PageContent[] }> => {
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

  const content: PageContent[] = [];
  let previewImage = '';

  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    // Higher scale for readability (2.0 is usually crystal clear)
    const viewport = page.getViewport({ scale: 2.0 });

    const canvas = document.createElement('canvas');
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas error');

    canvas.height = viewport.height;
    canvas.width = viewport.width;

    await page.render({ canvasContext: context, viewport }).promise;

    // Compress to JPEG at 0.7 quality for balance between size and readability
    const imageData = canvas.toDataURL('image/jpeg', 0.7);

    // Grab text snippet for internal indexing/search
    const textContent = await page.getTextContent();
    const textSnippet = textContent.items.map((it: any) => it.str).join(' ').slice(0, 200);

    if (i === 1) {
      previewImage = imageData;
    }

    content.push({
      pageIndex: i,
      imageData,
      textSnippet,
      width: viewport.width,
      height: viewport.height
    });
  }

  return { previewImage, content };
};

