interface UploadModalProps {
  onUploadComplete: () => void;
}

const UploadModal: React.FC<UploadModalProps> = ({ onUploadComplete }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [status, setStatus] = useState<'idle' | 'processing' | 'building' | 'success' | 'error'>('idle');
  const [error, setError] = useState<string | null>(null);
  const [previewImg, setPreviewImg] = useState<string>('');
  const [deconstructedData, setDeconstructedData] = useState<any>(null);
  const [newBookId, setNewBookId] = useState<string>('');

  const [formData, setFormData] = useState<BookMetadata>({
    title: '',
    author: '',
    genre: 'General',
    hashtags: [],
    vibe: 'Modern'
  });
  const [tagInput, setTagInput] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleOpen = () => {
      setIsOpen(true);
      setStatus('idle');
      setError(null);
      setFormData({ title: '', author: '', genre: 'General', hashtags: [], vibe: 'Modern' });
    };
    window.addEventListener('open-upload-modal', handleOpen);
    return () => window.removeEventListener('open-upload-modal', handleOpen);
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || file.type !== 'application/pdf') {
      setError('Please upload a valid PDF file.');
      return;
    }

    try {
      setStatus('processing');
      setError(null);
      const { previewImage, content } = await deconstructPdf(file);
      setPreviewImg(previewImage);
      setDeconstructedData(content);
      setStatus('building');
    } catch (err: any) {
      setError(err.message || 'Error compiling PDF.');
      setStatus('error');
    }
  };

  const handlePublish = async () => {
    if (!formData.title || !formData.author || !deconstructedData) {
      setError('Title and Author are required.');
      return;
    }

    try {
      const id = Math.random().toString(36).substr(2, 9);
      const newBook: Book = {
        id,
        previewImage: previewImg,
        metadata: formData,
        content: deconstructedData,
        uploadDate: Date.now(),
        likes: 0,
        shares: 0
      };

      await saveBook(newBook);
      setNewBookId(id);
      setStatus('success');
      onUploadComplete();
    } catch (err) {
      setError('Database error: Make sure you have enough disk space.');
      setStatus('error');
    }
  };

  const addTag = () => {
    const tag = tagInput.trim();
    if (tag && !formData.hashtags.includes(tag)) {
      setFormData({ ...formData, hashtags: [...formData.hashtags, tag.startsWith('#') ? tag : `#${tag}`] });
      setTagInput('');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-slate-950/80 backdrop-blur-md"
        onClick={() => status !== 'processing' && setIsOpen(false)}
      />

      <div className="relative bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
        <div className="p-8 md:p-12">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">
              {status === 'building' ? 'Finalize Site' : 'New Hash Site'}
            </h2>
            <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
              <X size={24} />
            </button>
          </div>

          {status === 'idle' || status === 'error' ? (
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="border-4 border-dashed border-slate-100 rounded-[2.5rem] p-16 text-center cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/30 transition-all group"
            >
              <input type="file" ref={fileInputRef} className="hidden" accept="application/pdf" onChange={handleFileChange} />
              <div className="bg-indigo-600 text-white w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-8 group-hover:scale-110 group-hover:rotate-3 transition-transform">
                <Upload size={40} />
              </div>
              <h3 className="text-xl font-black mb-2">Select a PDF to Deconstruct</h3>
              <p className="text-slate-400 font-bold text-sm">We'll turn every page into a social post.</p>
              {error && <p className="text-red-500 mt-6 font-black bg-red-50 py-2 px-4 rounded-xl">{error}</p>}
            </div>
          ) : status === 'processing' ? (
            <div className="py-24 text-center">
              <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-8" />
              <p className="text-xl font-black text-slate-800 tracking-tighter">DECONSTRUCTING BINARY...</p>
              <p className="text-slate-400 font-bold mt-2">Generating high-fidelity page snapshots</p>
            </div>
          ) : status === 'building' ? (
            <div className="grid md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <div className="aspect-[3/4] rounded-2xl overflow-hidden border-4 border-slate-50 shadow-xl">
                  <img src={previewImg} className="w-full h-full object-cover" alt="Preview" />
                </div>
                <div className="bg-slate-50 p-3 rounded-xl border border-slate-100">
                  <p className="text-center text-[9px] font-black text-slate-400 uppercase tracking-widest">Compiler v2.0 Success</p>
                </div>
              </div>

              <div className="space-y-4">
                <div className="space-y-3">
                  <div className="relative">
                    <TypeIcon size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Title" 
                      className="w-full bg-slate-50 border-none rounded-xl py-3 pl-10 pr-4 font-bold text-sm focus:ring-2 focus:ring-indigo-500"
                      value={formData.title}
                      onChange={e => setFormData({...formData, title: e.target.value})}
                    />
                  </div>
                  <div className="relative">
                    <User size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Author" 
                      className="w-full bg-slate-50 border-none rounded-xl py-3 pl-10 pr-4 font-bold text-sm focus:ring-2 focus:ring-indigo-500"
                      value={formData.author}
                      onChange={e => setFormData({...formData, author: e.target.value})}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <input 
                      type="text" 
                      placeholder="Genre" 
                      className="bg-slate-50 border-none rounded-xl py-3 px-4 font-bold text-sm"
                      value={formData.genre}
                      onChange={e => setFormData({...formData, genre: e.target.value})}
                    />
                    <input 
                      type="text" 
                      placeholder="Vibe" 
                      className="bg-slate-50 border-none rounded-xl py-3 px-4 font-bold text-sm"
                      value={formData.vibe}
                      onChange={e => setFormData({...formData, vibe: e.target.value})}
                    />
                  </div>
                  <div className="flex gap-2">
                    <input 
                      type="text" 
                      placeholder="#tags" 
                      className="flex-1 bg-slate-50 border-none rounded-xl py-3 px-4 text-sm font-bold"
                      value={tagInput}
                      onChange={e => setTagInput(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && addTag()}
                    />
                    <button onClick={addTag} className="bg-slate-900 text-white px-4 rounded-xl font-bold text-xs uppercase">Add</button>
                  </div>
                </div>

                <button 
                  onClick={handlePublish}
                  className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-lg shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-all mt-4"
                >
                  PUBLISH SITE
                </button>
              </div>
            </div>
          ) : (
            <div className="py-12 text-center">
              <div className="w-20 h-20 bg-green-100 text-green-600 rounded-3xl flex items-center justify-center mx-auto mb-8 animate-bounce">
                <CheckCircle size={48} />
              </div>
              <h3 className="text-3xl font-black mb-4 uppercase italic">Site Generated!</h3>
              <p className="text-slate-500 font-bold mb-8">The binary has been successfully hashed to a social site.</p>

              <div className="flex flex-col gap-3">
                <a 
                  href={`${window.location.origin}${window.location.pathname}#/book/${newBookId}`}
                  target="_blank"
                  rel="noreferrer"
                  className="bg-indigo-600 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-indigo-700"
                >
                  <ExternalLink size={20} />
                  VIEW LIVE SITE
                </a>
                <button 
                  onClick={() => setIsOpen(false)}
                  className="text-slate-400 font-bold hover:text-slate-900 transition-colors py-2 uppercase tracking-widest text-xs"
                >
                  Done
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

