import { PageContent } from '../types';

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

export const deconstructPdf = async (file: File): Promise<{ previewImage: string; content: PageContent[] }> => {
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

  const content: PageContent[] = [];
  let previewImage = '';

  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    // Use scale 1.5x for a perfect balance of clarity and storage stability
    const viewport = page.getViewport({ scale: 1.5 });

    const canvas = document.createElement('canvas');
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas rendering context not available');

    canvas.height = viewport.height;
    canvas.width = viewport.width;

    // Explicitly wait for the render task
    const renderTask = page.render({ canvasContext: context, viewport });
    await renderTask.promise;

    // Capture as JPEG to keep the "Hash Site" lightweight
    const imageData = canvas.toDataURL('image/jpeg', 0.8);

    // Extract text snippet for the "Social Caption"
    const textContent = await page.getTextContent();
    const textSnippet = textContent.items
      .map((it: any) => it.str)
      .join(' ')
      .slice(0, 150) + '...';

    if (i === 1) {
      previewImage = imageData;
    }

    content.push({
      pageIndex: i,
      imageData,
      textSnippet,
      width: viewport.width,
      height: viewport.height
    });

    // Immediate memory cleanup
    canvas.width = 0;
    canvas.height = 0;
  }

  return { previewImage, content };
};

