import React, { useState, useEffect, useRef } from 'react';
import { X, Upload, CheckCircle, Type, User, Bookmark } from 'lucide-react';
import { processPdfForStore } from '../services/pdfService';
import { saveBook } from '../services/db';
import { BookMetadata, BookData } from '../types';

interface UploadModalProps {
  onUploadComplete: () => void;
}

const UploadModal: React.FC<UploadModalProps> = ({ onUploadComplete }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');
  const [pdfInfo, setPdfInfo] = useState<any>(null);
  const [formData, setFormData] = useState({ title: '', author: '', genre: 'Literature' });
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleOpen = () => {
      setIsOpen(true);
      setStatus('idle');
      setPdfInfo(null);
    };
    window.addEventListener('open-upload-modal', handleOpen);
    return () => window.removeEventListener('open-upload-modal', handleOpen);
  }, []);

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setStatus('processing');
    const info = await processPdfForStore(file);
    setPdfInfo(info);
    setFormData(prev => ({ ...prev, title: file.name.replace('.pdf', '') }));
    setStatus('idle');
  };

  const publish = async () => {
    if (!pdfInfo) return;
    const id = Math.random().toString(36).substring(2, 11);

    const metadata: BookMetadata = {
      id,
      thumbnail: pdfInfo.thumbnail,
      title: formData.title,
      author: formData.author,
      genre: formData.genre,
      pages: pdfInfo.pageCount,
      uploadDate: Date.now()
    };

    const data: BookData = {
      id,
      pdfData: pdfInfo.pdfData
    };

    await saveBook(metadata, data);
    setStatus('success');
    onUploadComplete();
  };

