const STORAGE_KEY = 'socialbook_cloud_storage';

const getLocalStorageData = (): Record<string, ArrayBuffer> => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : {};
};

/**
 * GLOBAL DATABASE (50MB LIMIT)
 * We use IndexedDB to simulate the fast local cache, 
 * but logic is structured for Supabase Metadata.
 */
export const saveBook = async (metadata: BookMetadata, data: BookData): Promise<void> => {
  // 1. Save Metadata to "Database" (The 50MB target)
  const db = await initDB();
  const tx = db.transaction(['book_metadata', 'book_data'], 'readwrite');
  tx.objectStore('book_metadata').put(metadata);
  tx.objectStore('book_data').put(data);

  return new Promise((resolve) => {
    tx.oncomplete = () => resolve();
  });
};

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve) => {
    const request = indexedDB.open('GlobalBookstoreDB', 4);
    request.onupgradeneeded = (e: any) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains('book_metadata')) db.createObjectStore('book_metadata', { keyPath: 'id' });
      if (!db.objectStoreNames.contains('book_data')) db.createObjectStore('book_data', { keyPath: 'id' });
    };
    request.onsuccess = () => resolve(request.result);
  });
};

export const getAllMetadata = async (): Promise<BookMetadata[]> => {
  const db = await initDB();
  return new Promise((resolve) => {
    const request = db.transaction('book_metadata', 'readonly').objectStore('book_metadata').getAll();
    request.onsuccess = () => resolve(request.result);
  });
};

export const getBookMetadata = async (id: string): Promise<BookMetadata | null> => {
  const db = await initDB();
  return new Promise((resolve) => {
    const request = db.transaction('book_metadata', 'readonly').objectStore('book_metadata').get(id);
    request.onsuccess = () => resolve(request.result || null);
  });
};

export const getBookData = async (id: string): Promise<BookData | null> => {
  const db = await initDB();
  return new Promise((resolve) => {
    const request = db.transaction('book_data', 'readonly').objectStore('book_data').get(id);
    request.onsuccess = () => resolve(request.result || null);
  });
};

// @ts-ignore
const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

export const processPdfForStore = async (file: File) => {
  const arrayBuffer = await file.arrayBuffer();
  const bufferForProcessing = arrayBuffer.slice(0);

  const pdf = await pdfjsLib.getDocument({ data: bufferForProcessing }).promise;
  const page = await pdf.getPage(1);

  // Use a smaller scale for the storefront thumbnail to save DB space
  const viewport = page.getViewport({ scale: 0.6 });
  const canvas = document.createElement('canvas');
  const context = canvas.getContext('2d');

  if (context) {
    canvas.height = viewport.height;
    canvas.width = viewport.width;
    await page.render({ canvasContext: context, viewport }).promise;
  }

  // Use 0.6 quality to ensure each thumbnail is < 30KB
  // 50MB / 30KB = ~1,600 books capacity
  const thumbnail = canvas.toDataURL('image/jpeg', 0.6);

  canvas.width = 0;
  canvas.height = 0;

  return {
    thumbnail,
    pdfData: arrayBuffer,
    pageCount: pdf.numPages
  };
};

export const renderPdfPage = async (pdfData: ArrayBuffer, pageNum: number, container: HTMLCanvasElement) => {
  const bufferForRendering = pdfData.slice(0);
  const pdf = await pdfjsLib.getDocument({ data: bufferForRendering }).promise;
  const page = await pdf.getPage(pageNum);
  const viewport = page.getViewport({ scale: 1.5 });

  const context = container.getContext('2d');
  if (context) {
    container.height = viewport.height;
    container.width = viewport.width;
    await page.render({ canvasContext: context, viewport }).promise;
  }
  return pdf.numPages;
};

