import { createClient } from '@supabase/supabase-js';
import { BookMetadata, BookData } from '../types';

// These should be configured in your environment
const supabaseUrl = (process.env as any).SUPABASE_URL || '';
const supabaseAnonKey = (process.env as any).SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const BUCKET_NAME = 'books';

export const saveBook = async (metadata: BookMetadata, data: BookData): Promise<void> => {
  // 1. Upload PDF to Supabase Storage
  const { error: storageError } = await supabase.storage
    .from(BUCKET_NAME)
    .upload(`${metadata.id}.pdf`, data.pdfData, {
      contentType: 'application/pdf',
      upsert: true
    });

  if (storageError) throw storageError;

  // 2. Insert Metadata into Supabase Database
  // Note: Tables should have columns matching these keys
  const { error: dbError } = await supabase
    .from('books')
    .insert([{
      id: metadata.id,
      title: metadata.title,
      author: metadata.author,
      genre: metadata.genre,
      pages: metadata.pages,
      thumbnail: metadata.thumbnail,
      upload_date: new Date(metadata.uploadDate).toISOString()
    }]);

  if (dbError) throw dbError;
};

export const getAllMetadata = async (): Promise<BookMetadata[]> => {
  const { data, error } = await supabase
    .from('books')
    .select('*')
    .order('upload_date', { ascending: false });

  if (error) throw error;

  return data.map(item => ({
    id: item.id,
    title: item.title,
    author: item.author,
    genre: item.genre,
    pages: item.pages,
    thumbnail: item.thumbnail,
    uploadDate: new Date(item.upload_date).getTime()
  }));
};

export const getBookMetadata = async (id: string): Promise<BookMetadata | null> => {
  const { data, error } = await supabase
    .from('books')
    .select('*')
    .eq('id', id)
    .single();

  if (error) return null;

  return {
    id: data.id,
    title: data.title,
    author: data.author,
    genre: data.genre,
    pages: data.pages,
    thumbnail: data.thumbnail,
    uploadDate: new Date(data.upload_date).getTime()
  };
};

export const getBookData = async (id: string): Promise<BookData | null> => {
  const { data, error } = await supabase.storage
    .from(BUCKET_NAME)
    .download(`${id}.pdf`);

  if (error || !data) return null;

  const arrayBuffer = await data.arrayBuffer();

  return {
    id,
    pdfData: arrayBuffer
  };
};

