  if (supabaseInstance) return supabaseInstance;

  // Safely access process.env if available in the environment
  const env = (typeof process !== 'undefined' && process.env) ? process.env : {};
  const supabaseUrl = (env as any).SUPABASE_URL;
  const supabaseAnonKey = (env as any).SUPABASE_ANON_KEY;

  // Strict check to prevent calling createClient with bad/missing values
  if (!supabaseUrl || typeof supabaseUrl !== 'string' || !supabaseUrl.startsWith('http') || supabaseUrl === 'undefined') {
    throw new Error('SUPABASE_URL is missing or invalid. Please check your environment variables.');
  }

  if (!supabaseAnonKey || typeof supabaseAnonKey !== 'string' || supabaseAnonKey === 'undefined') {
    throw new Error('SUPABASE_ANON_KEY is missing or invalid. Please check your environment variables.');
  }

  supabaseInstance = createClient(supabaseUrl, supabaseAnonKey);
  return supabaseInstance;
};

