/**
 * Saves a book's metadata to Postgres and its PDF data to Storage.
 */
export const saveBook = async (metadata: BookMetadata, data: BookData): Promise<void> => {
  const supabase = getSupabase();

  // 1. Upload PDF to Supabase Storage bucket 'books'
  const { error: storageError } = await supabase.storage
    .from(BUCKET_NAME)
    .upload(`${metadata.id}.pdf`, data.pdfData, {
      contentType: 'application/pdf',
      upsert: true
    });

  if (storageError) throw storageError;

  // 2. Insert Metadata into the 'books' table
  const { error: dbError } = await supabase
    .from('books')
    .insert([{
      id: metadata.id,
      title: metadata.title,
      author: metadata.author,
      genre: metadata.genre,
      pages: metadata.pages,
      thumbnail: metadata.thumbnail,
      upload_date: new Date(metadata.uploadDate).toISOString()
    }]);

  if (dbError) throw dbError;
};

