const App: React.FC = () => {
  const [books, setBooks] = useState<BookMetadata[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isConfigured, setIsConfigured] = useState<boolean>(true);

  const refreshBooks = async () => {
    const supabase = getSupabase();
    if (!supabase) {
      setIsConfigured(false);
      return;
    }
    setIsConfigured(true);

    try {
      const data = await getAllMetadata();
      setBooks(data);
      setError(null);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'An unexpected error occurred while connecting to Supabase.');
    }
  };

  useEffect(() => {
    refreshBooks();
  }, []);

  if (!isConfigured) {
    return <SetupGuide />;
  }

  return (
    <Router>
      <div className="min-h-screen flex flex-col font-sans selection:bg-indigo-100 selection:text-indigo-600">
        <Navbar />
        <Routes>
          <Route path="/" element={<HomePage books={books} error={error} />} />
          <Route path="/book/:id" element={<SocialPage />} />
          <Route path="/read/:id" element={<BookViewer />} />
        </Routes>
        <UploadModal onUploadComplete={refreshBooks} />
      </div>
    </Router>
  );
};

