import React, { useEffect, useState, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { BookMetadata, BookData } from '../types';
import { renderPdfPage } from '../services/pdfService';
import { getBookMetadata, getBookData } from '../services/db';
import { 
  ChevronLeft, 
  ChevronRight, 
  X, 
  Share2, 
  Check, 
  Hash, 
  Play, 
  Pause, 
  Settings2,
  Tv
} from 'lucide-react';

const SPEEDS = {
  AMBIENT: 15000,
  STANDARD: 8000,
  RAPID: 4000
};

const BookViewer: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [metadata, setMetadata] = useState<BookMetadata | null>(null);
  const [pdfData, setPdfData] = useState<BookData | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [copied, setCopied] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playSpeed, setPlaySpeed] = useState<keyof typeof SPEEDS>('STANDARD');
  const [progress, setProgress] = useState(0);
  const [uiVisible, setUiVisible] = useState(true);
  const [isTransitioning, setIsTransitioning] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const uiTimeoutRef = useRef<number | null>(null);
  const lastInteractionRef = useRef<number>(Date.now());

  useEffect(() => {
    if (id) {
      Promise.all([getBookMetadata(id), getBookData(id)]).then(([meta, data]) => {
        setMetadata(meta);
        setPdfData(data);
        setLoading(false);
      });
    }
  }, [id]);

  useEffect(() => {
    if (pdfData && canvasRef.current) {
      setIsTransitioning(true);
      const timer = setTimeout(() => {
        renderPdfPage(pdfData.pdfData, currentPage, canvasRef.current!).then(() => {
          setIsTransitioning(false);
        });
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [pdfData, currentPage]);

  // TV Playback Logic
  useEffect(() => {
    let interval: number;
    let progressInterval: number;

    if (isPlaying && metadata) {
      const startTime = Date.now();
      const duration = SPEEDS[playSpeed];

      progressInterval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        setProgress(Math.min((elapsed / duration) * 100, 100));
      }, 50);

      interval = window.setInterval(() => {
        setCurrentPage(prev => {
          if (prev >= metadata.pages) {
            setIsPlaying(false);
            return prev;
          }
          return prev + 1;
        });
        setProgress(0);
      }, duration);
    } else {
      setProgress(0);
    }

    return () => {
      clearInterval(interval);
      clearInterval(progressInterval);
    };
  }, [isPlaying, playSpeed, metadata, currentPage]);

  // Auto-hide UI Logic
  useEffect(() => {
    const handleMouseMove = () => {
      setUiVisible(true);
      lastInteractionRef.current = Date.now();
      if (uiTimeoutRef.current) window.clearTimeout(uiTimeoutRef.current);

      if (isPlaying) {
        uiTimeoutRef.current = window.setTimeout(() => {
          if (Date.now() - lastInteractionRef.current >= 3000) {
            setUiVisible(false);
          }
        }, 3000);
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [isPlaying]);

  const copyUrl = () => {
    navigator.clipboard.writeText(window.location.href);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (loading) return (
    <div className="h-screen flex items-center justify-center bg-slate-950">
      <div className="relative">
        <div className="w-16 h-16 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin" />
        <div className="absolute inset-0 flex items-center justify-center">
          <Hash size={16} className="text-indigo-500 animate-pulse" />
        </div>
      </div>
    </div>
  );

  if (!metadata || !pdfData) return (
    <div className="h-screen flex items-center justify-center bg-slate-950 text-white">
      <div className="text-center space-y-4">
        <h2 className="text-2xl font-black uppercase italic tracking-tighter text-red-500">Hash Site Corrupted</h2>
        <Link to="/" className="inline-block bg-white text-black px-6 py-2 rounded-full font-bold uppercase text-xs">Return to Shelf</Link>
      </div>
    </div>
  );

  return (
    <div className={`min-h-screen bg-[#020617] text-white selection:bg-indigo-500 selection:text-white overflow-x-hidden transition-all duration-700 ${!uiVisible ? 'cursor-none' : ''}`}>

      {/* Cinematic TV Timeline (Top) */}
      <div className={`fixed top-0 left-0 right-0 z-[60] h-1 bg-white/5 transition-opacity duration-500 ${isPlaying ? 'opacity-100' : 'opacity-0'}`}>
        <div 
          className="h-full bg-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.8)] transition-all duration-75 linear"
          style={{ width: `${progress}%` }}
        />
      </div>

      {/* Cinematic Ambient Glow */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-indigo-500/10 blur-[120px] rounded-full transition-opacity duration-1000 ${isPlaying ? 'opacity-40' : 'opacity-100'}`} />
      </div>

      {/* Floating HUD Header */}
      <nav className={`fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[95%] max-w-5xl transition-all duration-500 transform ${uiVisible ? 'translate-y-0 opacity-100' : '-translate-y-12 opacity-0'}`}>
        <div className="bg-slate-900/40 backdrop-blur-xl border border-white/10 rounded-2xl h-16 px-6 flex items-center justify-between shadow-2xl">
          <div className="flex items-center gap-4">
            <Link to={`/book/${id}`} className="p-2 hover:bg-white/10 rounded-xl transition-all text-slate-400 hover:text-white">
              <X size={20} />
            </Link>
            <div className="hidden md:block">
              <div className="flex items-center gap-2 mb-1">
                {isPlaying && <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />}
                <h1 className="text-xs font-black uppercase tracking-widest truncate max-w-[150px] leading-none">
                  {isPlaying ? 'Live Broadcast' : metadata.title}
                </h1>
              </div>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest leading-none">Hash: {metadata.id}</p>
            </div>
          </div>

          <div className="flex items-center gap-2 bg-black/40 p-1 rounded-xl border border-white/5">
            <button 
              onClick={() => setIsPlaying(!isPlaying)}
              className={`p-2 rounded-lg transition-all flex items-center gap-2 ${isPlaying ? 'bg-indigo-600 text-white' : 'hover:bg-white/10 text-slate-300'}`}
            >
              {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" />}
              <span className="text-[10px] font-black uppercase tracking-widest pr-1 hidden sm:block">
                {isPlaying ? 'On Air' : 'TV Mode'}
              </span>
            </button>

            <div className="w-px h-6 bg-white/10 mx-1 hidden sm:block" />

            <button 
              disabled={currentPage <= 1 || isPlaying} 
