            </button>
          </div>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="pt-32 pb-24 flex justify-center px-4 relative">
        <div className={`relative transition-all duration-700 transform ${isTransitioning ? 'scale-[0.98] opacity-40 blur-sm' : 'scale-100 opacity-100 blur-0'}`}>
