          <div className="absolute inset-0 bg-white/5 blur-3xl rounded-sm scale-105 pointer-events-none" />

          <div className="relative shadow-[0_0_100px_-20px_rgba(0,0,0,0.8),0_0_40px_-10px_rgba(99,102,241,0.2)] bg-white rounded-sm overflow-hidden border border-white/5">
            <canvas ref={canvasRef} className="max-w-full h-auto block" />

            {/* Fine texture overlay */}
