              >
                <ChevronLeft size={32} />
              </button>
              <button 
                disabled={currentPage >= metadata.pages}
                onClick={() => setCurrentPage(prev => prev + 1)}
                className={`fixed right-4 lg:right-12 top-1/2 -translate-y-1/2 p-4 bg-white/5 hover:bg-white/10 rounded-full text-slate-500 hover:text-white transition-all backdrop-blur-md border border-white/5 hidden md:block ${uiVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
              >
                <ChevronRight size={32} />
              </button>
            </>
          )}
        </div>
      </main>

      {/* Mobile Page Progress Pill */}
      <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 z-50 transition-all duration-500 ${uiVisible ? 'translate-y-0 opacity-100' : 'translate-y-12 opacity-0'}`}>
        <div className="bg-slate-900/80 backdrop-blur-md border border-white/10 px-6 py-2 rounded-full shadow-2xl flex items-center gap-4">
          <div className="flex items-center gap-2">
             <Tv size={12} className={isPlaying ? 'text-indigo-400' : 'text-slate-500'} />
             <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Page</span>
          </div>
          <div className="h-1 w-24 bg-white/10 rounded-full overflow-hidden">
