import React, { useEffect, useState, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { BookMetadata, BookData } from '../types';
import { renderPdfPage } from '../services/pdfService';
import { getBookMetadata, getBookData } from '../services/db';
import { 
  ChevronLeft, 
  ChevronRight, 
  X, 
  Share2, 
  Check, 
  Hash, 
  Play, 
  Pause, 
  Tv,
  Maximize2
} from 'lucide-react';

const SPEEDS = {
  AMBIENT: 15000,
  STANDARD: 8000,
  RAPID: 4000
};

const BookViewer: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [metadata, setMetadata] = useState<BookMetadata | null>(null);
  const [pdfData, setPdfData] = useState<BookData | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [copied, setCopied] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playSpeed, setPlaySpeed] = useState<keyof typeof SPEEDS>('STANDARD');
  const [progress, setProgress] = useState(0);
  const [uiVisible, setUiVisible] = useState(true);
  const [isTransitioning, setIsTransitioning] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const uiTimeoutRef = useRef<number | null>(null);
  const lastInteractionRef = useRef<number>(Date.now());

  useEffect(() => {
    if (id) {
      Promise.all([getBookMetadata(id), getBookData(id)]).then(([meta, data]) => {
        setMetadata(meta);
        setPdfData(data);
        setLoading(false);
      });
    }
  }, [id]);

  useEffect(() => {
    if (pdfData && canvasRef.current) {
      setIsTransitioning(true);
      const timer = setTimeout(() => {
        renderPdfPage(pdfData.pdfData, currentPage, canvasRef.current!).then(() => {
          setIsTransitioning(false);
        });
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [pdfData, currentPage]);

  // TV Playback Logic
  useEffect(() => {
    let interval: number;
    let progressInterval: number;

    if (isPlaying && metadata) {
      const startTime = Date.now();
      const duration = SPEEDS[playSpeed];

      progressInterval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        setProgress(Math.min((elapsed / duration) * 100, 100));
      }, 50);

      interval = window.setInterval(() => {
        setCurrentPage(prev => {
          if (prev >= metadata.pages) {
            setIsPlaying(false);
            return prev;
          }
          return prev + 1;
        });
        setProgress(0);
      }, duration);
    } else {
      setProgress(0);
    }

    return () => {
      clearInterval(interval);
      clearInterval(progressInterval);
    };
  }, [isPlaying, playSpeed, metadata, currentPage]);

  // Auto-hide UI Logic
  useEffect(() => {
    const handleMouseMove = () => {
      setUiVisible(true);
      lastInteractionRef.current = Date.now();
      if (uiTimeoutRef.current) window.clearTimeout(uiTimeoutRef.current);

      if (isPlaying) {
        uiTimeoutRef.current = window.setTimeout(() => {
          if (Date.now() - lastInteractionRef.current >= 3000) {
            setUiVisible(false);
          }
        }, 3000);
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [isPlaying]);

  const copyUrl = () => {
    navigator.clipboard.writeText(window.location.href);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (loading) return (
    <div className="h-screen flex items-center justify-center bg-slate-950">
      <div className="relative">
        <div className="w-16 h-16 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin" />
        <div className="absolute inset-0 flex items-center justify-center">
          <Hash size={16} className="text-indigo-500 animate-pulse" />
        </div>
      </div>
    </div>
  );

  if (!metadata || !pdfData) return (
    <div className="h-screen flex items-center justify-center bg-slate-950 text-white">
      <div className="text-center space-y-4">
        <h2 className="text-2xl font-black uppercase italic tracking-tighter text-red-500">Hash Site Corrupted</h2>
        <Link to="/" className="inline-block bg-white text-black px-6 py-2 rounded-full font-bold uppercase text-xs">Return to Shelf</Link>
      </div>
    </div>
  );

  return (
    <div className={`h-screen w-screen bg-[#020617] text-white selection:bg-indigo-500 selection:text-white overflow-hidden transition-all duration-700 ${!uiVisible ? 'cursor-none' : ''}`}>

      {/* Cinematic TV Timeline (Top) */}
      <div className={`fixed top-0 left-0 right-0 z-[60] h-1 bg-white/5 transition-opacity duration-500 ${isPlaying ? 'opacity-100' : 'opacity-0'}`}>
        <div 
          className="h-full bg-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.8)] transition-all duration-75 linear"
          style={{ width: `${progress}%` }}
        />
      </div>

      {/* Cinematic Ambient Glow */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-indigo-500/10 blur-[120px] rounded-full transition-opacity duration-1000 ${isPlaying ? 'opacity-40' : 'opacity-100'}`} />
      </div>

      {/* Floating HUD Header - Minimalism focus */}
      <nav className={`fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[95%] max-w-5xl transition-all duration-500 transform ${uiVisible ? 'translate-y-0 opacity-100' : '-translate-y-16 opacity-0'}`}>
        <div className="bg-slate-900/40 backdrop-blur-xl border border-white/10 rounded-2xl h-16 px-6 flex items-center justify-between shadow-2xl">
          <div className="flex items-center gap-4">
            <Link to={`/book/${id}`} className="p-2 hover:bg-white/10 rounded-xl transition-all text-slate-400 hover:text-white">
              <X size={20} />
            </Link>
            <div className="hidden md:block">
              <div className="flex items-center gap-2 mb-1">
                {isPlaying && <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />}
                <h1 className="text-xs font-black uppercase tracking-widest truncate max-w-[200px] leading-none">
                  {isPlaying ? 'Live Broadcast' : metadata.title}
                </h1>
              </div>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest leading-none">Hash: {metadata.id}</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden lg:flex items-center gap-1 bg-black/20 p-1 rounded-lg border border-white/5">
              {(['AMBIENT', 'STANDARD', 'RAPID'] as const).map((s) => (
                <button
                  key={s}
                  onClick={() => setPlaySpeed(s)}
                  className={`px-2 py-1 rounded text-[8px] font-black tracking-widest uppercase transition-all ${playSpeed === s ? 'bg-white text-black' : 'text-slate-500 hover:text-white'}`}
                >
                  {s[0]}
                </button>
              ))}
            </div>
            <button 
              onClick={copyUrl}
              className="flex items-center gap-2 bg-white text-black px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-500 hover:text-white transition-all shadow-lg"
            >
              {copied ? <Check size={14} /> : <Share2 size={14} />}
              <span className="hidden sm:inline">{copied ? 'Copied' : 'Share'}</span>
            </button>
          </div>
        </div>
      </nav>

      {/* Main Cinematic Stage - 100% Clear of Nav Overlays */}
      <main className="h-full w-full flex items-center justify-center p-4">
        <div className={`relative transition-all duration-700 transform flex items-center justify-center max-h-full max-w-full ${isTransitioning ? 'scale-[0.98] opacity-40 blur-sm' : 'scale-100 opacity-100 blur-0'}`}>
          {/* Paper Effect Glow */}
          <div className="absolute inset-0 bg-white/5 blur-3xl rounded-sm scale-105 pointer-events-none" />

          <div className="relative shadow-[0_0_100px_-20px_rgba(0,0,0,0.8),0_0_40px_-10px_rgba(99,102,241,0.2)] bg-white rounded-sm overflow-hidden border border-white/5 max-h-[82vh] flex items-center justify-center">
            <canvas ref={canvasRef} className="max-h-[82vh] w-auto block object-contain" />

            {/* Fine texture overlay */}
            <div className="absolute inset-0 pointer-events-none opacity-[0.04] mix-blend-multiply bg-[url('https://www.transparenttextures.com/patterns/paper-fibers.png')]" />

            {/* Subtle shadow on the left spine if page > 1 */}
            {currentPage > 1 && (
              <div className="absolute inset-y-0 left-0 w-8 bg-gradient-to-r from-black/20 to-transparent pointer-events-none" />
            )}
          </div>
        </div>
      </main>

      {/* Cinematic Remote Control (Bottom Consolidated) */}
      <div className={`fixed bottom-10 left-1/2 -translate-x-1/2 z-50 transition-all duration-500 transform ${uiVisible ? 'translate-y-0 opacity-100' : 'translate-y-16 opacity-0'}`}>
        <div className="bg-slate-900/80 backdrop-blur-xl border border-white/10 p-2 rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)] flex items-center gap-2 min-w-[320px]">

          {/* Previous Button */}
          <button 
            disabled={currentPage <= 1 || isPlaying} 
            onClick={() => setCurrentPage(prev => prev - 1)} 
            className="p-3 bg-white/5 hover:bg-white/10 disabled:opacity-5 rounded-full transition-all text-slate-300"
          >
            <ChevronLeft size={24} />
          </button>

          {/* TV / Playback Center */}
          <div className="flex-1 flex items-center gap-4 px-4 bg-black/40 rounded-full h-12 border border-white/5">
