import React, { useState, useEffect, useRef } from 'react';
import { X, Upload, CheckCircle, Type, User, ShieldCheck, AlertCircle, Terminal, Globe } from 'lucide-react';
import { processPdfForStore } from '../services/pdfService';
import { saveBook } from '../services/db';
import { BookMetadata, BookData } from '../types';

interface UploadModalProps {
  onUploadComplete: () => void;
}

const UploadModal: React.FC<UploadModalProps> = ({ onUploadComplete }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [status, setStatus] = useState<'idle' | 'processing' | 'uploading' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');
  const [pdfInfo, setPdfInfo] = useState<any>(null);
  const [formData, setFormData] = useState({ title: '', author: '', genre: 'Literature' });
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleOpen = () => { setIsOpen(true); setStatus('idle'); setPdfInfo(null); setErrorMessage(''); };
    window.addEventListener('open-upload-modal', handleOpen);
    return () => window.removeEventListener('open-upload-modal', handleOpen);
  }, []);

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStatus('processing');
    try {
      const info = await processPdfForStore(file);
      setPdfInfo(info);
      setFormData(prev => ({ ...prev, title: file.name.replace('.pdf', '') }));
      setStatus('idle');
    } catch (err) { setStatus('error'); setErrorMessage('Failed to process PDF.'); }
  };

  const publish = async () => {
    if (!pdfInfo) return;
    setStatus('uploading');
    try {
      const id = crypto.randomUUID().split('-')[0];
      const metadata: BookMetadata = { id, thumbnail: pdfInfo.thumbnail, title: formData.title, author: formData.author, genre: formData.genre, pages: pdfInfo.pageCount, uploadDate: Date.now() };
      const data: BookData = { id, pdfData: pdfInfo.pdfData };
      await saveBook(metadata, data);
      setStatus('success');
      onUploadComplete();
    } catch (err: any) { setStatus('error'); setErrorMessage(err.message || 'Sync failed.'); }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/90 backdrop-blur-md" onClick={() => setIsOpen(false)} />
      <div className="relative bg-[#0a0a0a] w-full max-w-xl rounded-[2.5rem] shadow-[0_0_100px_rgba(0,194,255,0.1)] overflow-hidden border border-white/5">
        <div className="p-12">
          <div className="flex justify-between items-center mb-12">
            <div>
              <h2 className="text-3xl font-black italic tracking-tighter text-white uppercase">Neural_Ingest</h2>
              <p className="text-[10px] font-black text-[#00c2ff] uppercase tracking-[0.4em] mt-2 leading-none">Archiving to Nexus Cloud</p>
            </div>
            <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-white/5 rounded-full text-slate-500"><X size={24} /></button>
          </div>

          {status === 'error' ? (
            <div className="py-12 text-center">
              <AlertCircle size={64} className="text-red-600 mx-auto mb-6" />
              <h3 className="text-2xl font-black text-white uppercase italic">Ingest_Failed</h3>
              <p className="text-slate-500 mb-10 text-xs font-bold uppercase tracking-widest mt-4">{errorMessage}</p>
              <button onClick={() => setStatus('idle')} className="w-full bg-white text-black py-5 rounded-2xl font-black uppercase tracking-widest">Retry_Attempt</button>
            </div>
          ) : status === 'success' ? (
            <div className="py-12 text-center animate-in zoom-in duration-500">
              <ShieldCheck size={64} className="text-[#00c2ff] mx-auto mb-6 shadow-[0_0_30px_rgba(0,194,255,0.4)]" />
              <h3 className="text-2xl font-black text-white uppercase italic">Hash_Locked</h3>
              <p className="text-slate-500 mb-10 text-xs font-bold uppercase tracking-widest mt-4">Data successfully synced to digital archives.</p>
              <button onClick={() => setIsOpen(false)} className="w-full bg-[#00c2ff] text-black py-5 rounded-2xl font-black uppercase tracking-widest">Return_To_Shelf</button>
            </div>
          ) : status === 'uploading' ? (
            <div className="py-20 text-center">
              <div className="w-16 h-16 border-2 border-[#00c2ff]/20 border-t-[#00c2ff] rounded-full animate-spin mx-auto mb-8" />
              <p className="text-xl font-black text-white italic uppercase">Syncing_Segments...</p>
            </div>
          ) : !pdfInfo ? (
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="border-2 border-dashed border-white/5 rounded-[2rem] p-24 text-center cursor-pointer hover:border-[#00c2ff]/50 hover:bg-[#00c2ff]/5 transition-all group"
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFile} />
              <div className="w-20 h-20 bg-white/5 rounded-3xl flex items-center justify-center mx-auto mb-8 text-slate-600 group-hover:text-[#00c2ff] transition-all group-hover:scale-110">
                <Terminal size={40} />
              </div>
              <p className="text-lg font-black text-white uppercase tracking-widest">Ingest_PDF_Binary</p>
            </div>
          ) : (
            <div className="space-y-8">
              <div className="flex gap-8 p-8 bg-black rounded-3xl border border-white/5 items-center">
                <img src={pdfInfo.thumbnail} className="w-24 aspect-[3/4] object-cover rounded-xl shadow-2xl border border-white/10" alt="thumb" />
                <div className="flex-1 min-w-0">
                  <p className="text-[10px] font-black text-[#00c2ff] uppercase tracking-widest mb-2 opacity-60">Payload_Verified</p>
                  <p className="text-xl font-black text-white uppercase italic truncate">{formData.title}</p>
                </div>
              </div>
              <div className="space-y-4">
                <input value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} placeholder="Archive_Title" className="w-full bg-black border border-white/10 py-5 px-8 rounded-2xl text-sm font-black text-white focus:outline-none focus:border-[#00c2ff]/50 uppercase tracking-widest" />
                <input value={formData.author} onChange={e => setFormData({...formData, author: e.target.value})} placeholder="Originator_Name" className="w-full bg-black border border-white/10 py-5 px-8 rounded-2xl text-sm font-black text-white focus:outline-none focus:border-[#00c2ff]/50 uppercase tracking-widest" />
              </div>
              <button onClick={publish} className="w-full bg-white text-black py-6 rounded-2xl font-black text-lg hover:bg-[#00c2ff] transition-all shadow-2xl uppercase italic tracking-tighter">
                Confirm_Publish
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

